import{_ as a,o,c as n,ai as i}from"./chunks/framework.Bm4BMKaq.js";const m=JSON.parse('{"title":"How Execution Works","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/how-it-works/core/execution.md","filePath":"explanation/how-it-works/core/execution.md"}'),t={name:"explanation/how-it-works/core/execution.md"};function s(r,e,l,d,c,h){return o(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="how-execution-works" tabindex="-1">How Execution Works <a class="header-anchor" href="#how-execution-works" aria-label="Permalink to “How Execution Works”">​</a></h1><p>How command execution works under the hood, step by step.</p><h2 id="pipeline" tabindex="-1">Pipeline <a class="header-anchor" href="#pipeline" aria-label="Permalink to “Pipeline”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>argv</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ 1. Route ──────────── Match command from the nested command tree</span></span>
<span class="line"><span>  ├─ 2. Parse ──────────── Extract positional args and options (resolve aliases)</span></span>
<span class="line"><span>  ├─ 3. Plugin (pre) ────── onBeforeCommandExecution (global + command plugins; raw parsed args)</span></span>
<span class="line"><span>  ├─ 4. Middleware ─────── Matched command only; build ctx via next()</span></span>
<span class="line"><span>  ├─ 5. Validate ───────── Unknown-option policy, bequeath handlers, Zod positional &amp; options</span></span>
<span class="line"><span>  ├─ 6. Handler ────────── Execute command handler with validated params</span></span>
<span class="line"><span>  └─ 7. Plugin (post) ──── onAfterCommandExecution (always runs, even on error)</span></span></code></pre></div><h2 id="entry-point" tabindex="-1">Entry Point <a class="header-anchor" href="#entry-point" aria-label="Permalink to “Entry Point”">​</a></h2><p><code>executeCli()</code> receives <code>{ cli, args }</code> (args default to <code>process.argv.slice(2)</code>).</p><ol><li>Resolves the command from the tree</li><li>Runs the command pipeline</li><li>On error: formats and logs via <code>handleError()</code>, then <code>process.exit(1)</code></li><li><strong>Finally</strong>: runs <code>onDestroy</code> plugin hooks (always, even on error)</li></ol><p>Deprecation warnings are not emitted by the core execution layer. If you install the standard library <code>deprecationPlugin</code>, it will emit warnings via plugin hooks (e.g. <code>onInit</code> for the CLI and <code>onBeforeCommandExecution</code> for the matched command).</p><h2 id="routing" tabindex="-1">Routing <a class="header-anchor" href="#routing" aria-label="Permalink to “Routing”">​</a></h2><p>Walks the nested command tree by consuming argv segments:</p><ul><li>Each non-flag arg (<code>!startsWith(&#39;-&#39;)</code>) is matched against command <code>paths</code></li><li>On match: descend into that subcommand, consume the segment</li><li>On no match or flag: stop — current command is the target</li><li>Remaining argv is forwarded to the command as its own args</li></ul><h2 id="command-pipeline" tabindex="-1">Command Pipeline <a class="header-anchor" href="#command-pipeline" aria-label="Permalink to “Command Pipeline”">​</a></h2><p>This is the core of execution. Runs in this exact order:</p><h3 id="_1-alias-map" tabindex="-1">1. Alias Map <a class="header-anchor" href="#_1-alias-map" aria-label="Permalink to “1. Alias Map”">​</a></h3><p>Merges command option aliases (from Zod <code>.meta({ aliases })</code>) with bequeath option aliases into a single lookup map.</p><h3 id="_2-argument-parsing" tabindex="-1">2. Argument Parsing <a class="header-anchor" href="#_2-argument-parsing" aria-label="Permalink to “2. Argument Parsing”">​</a></h3><p>Splits raw argv into <code>{ positional: string[], options: Record&lt;string, any&gt; }</code> using mri with the alias map.</p><h3 id="_3-pre-execution-plugin-hooks" tabindex="-1">3. Pre-Execution Plugin Hooks <a class="header-anchor" href="#_3-pre-execution-plugin-hooks" aria-label="Permalink to “3. Pre-Execution Plugin Hooks”">​</a></h3><p>Runs <code>onBeforeCommandExecution</code> for global plugins, then command plugins, in order. Hooks receive <strong>unvalidated</strong> <code>parsedOptions</code> and <code>parsedPositionals</code>. If a hook throws, the rest of the pipeline (including middleware and handler) does not run.</p><h3 id="_4-middleware" tabindex="-1">4. Middleware <a class="header-anchor" href="#_4-middleware" aria-label="Permalink to “4. Middleware”">​</a></h3><p>Runs the <strong>matched command’s</strong> <code>middleware</code> array only (not parent commands’ arrays), in order. Each step receives frozen params <code>{ ctx, next, cli, command, halt }</code>. Context grows when a middleware <strong>returns</strong> <code>next({ ctx: { ... } })</code> (deep-merge via defu). Each middleware must <strong>return</strong> the result of <code>next()</code>. The final context is passed to bequeath option handlers and the command handler as <code>ctx</code>.</p><h3 id="_5-extraneous-options" tabindex="-1">5. Extraneous Options <a class="header-anchor" href="#_5-extraneous-options" aria-label="Permalink to “5. Extraneous Options”">​</a></h3><p>Checks parsed options against the schema + bequeath option names. Behavior depends on <code>throwOnExtrageousOptions</code>:</p><ul><li><code>&#39;throw&#39;</code> (default): throws <code>InvalidOptionsError</code></li><li><code>&#39;filter-out&#39;</code>: silently drops unknown options</li><li><code>&#39;pass-through&#39;</code>: keeps them for the handler</li></ul><h3 id="_6-bequeath-option-handlers" tabindex="-1">6. Bequeath Option Handlers <a class="header-anchor" href="#_6-bequeath-option-handlers" aria-label="Permalink to “6. Bequeath Option Handlers”">​</a></h3><p>Iterates bequeath options. If a bequeath option is present in parsed args:</p><ul><li>Validates its value against its Zod schema</li><li>If it has a handler (e.g. <code>--help</code>, <code>--version</code>): executes it and <strong>returns early</strong> (short-circuits the rest of the pipeline)</li></ul><h3 id="_7-positional-validation" tabindex="-1">7. Positional Validation <a class="header-anchor" href="#_7-positional-validation" aria-label="Permalink to “7. Positional Validation”">​</a></h3><p>Extracts the positional value, then runs <code>schema.parse()</code>. Throws <code>InvalidPositionalError</code> on failure.</p><h3 id="_8-options-validation" tabindex="-1">8. Options Validation <a class="header-anchor" href="#_8-options-validation" aria-label="Permalink to “8. Options Validation”">​</a></h3><p>Separates valid vs. extra options, then runs <code>schema.parse()</code> on valid options. For <code>&#39;pass-through&#39;</code> mode, extra options are merged back into the result.</p><h3 id="_9-handler" tabindex="-1">9. Handler <a class="header-anchor" href="#_9-handler" aria-label="Permalink to “9. Handler”">​</a></h3><p>Calls the command handler with:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{ positional, options, ctx, command, cli }</span></span></code></pre></div><h3 id="_10-post-execution-plugin-hooks" tabindex="-1">10. Post-Execution Plugin Hooks <a class="header-anchor" href="#_10-post-execution-plugin-hooks" aria-label="Permalink to “10. Post-Execution Plugin Hooks”">​</a></h3><p>Runs <code>onAfterCommandExecution</code> in a <code>finally</code> block — always executes, even if the handler threw. Hook errors are logged but don&#39;t override the original error.</p><h2 id="error-handling" tabindex="-1">Error Handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to “Error Handling”">​</a></h2><p>Errors are handled by <code>handleError()</code>, which distinguishes between:</p><ul><li><strong>Validation errors</strong> (<code>InvalidPositionalError</code>, <code>InvalidOptionsError</code>): structured Zod issues — each is logged with the field name and description extracted from the manifest</li><li><strong>Standard errors</strong>: logs the message</li><li><strong>Unknown errors</strong>: logs a generic message</li></ul><p>After logging, <code>executeCli()</code> calls <code>process.exit(1)</code>.</p>`,40)])])}const u=a(t,[["render",s]]);export{m as __pageData,u as default};
